$$
R.M.S. velocity, $\mathrm{v}_{\mathrm{rms}} \propto \sqrt{\mathrm{T}}$
$$
\begin{array}{ll} 
& \frac{\left(\mathrm{v}_{\mathrm{rms}}\right)_2}{\left(\mathrm{v}_{\mathrm{rms}}\right)_1}=\sqrt{\frac{\mathrm{T}_2}{\mathrm{~T}_1}}=2 \\
\therefore \quad & \frac{\mathrm{T}_2}{\mathrm{~T}_1}=4 \\
\therefore \quad & \mathrm{T}_2=4 \times 205=820 \mathrm{~K} \\
\therefore \quad & \mathrm{T}_2=547^{\circ} \mathrm{C}
\end{array}
$$

R.M.S. velocity is given by
$$
\begin{aligned}
& \mathrm{V}=\sqrt{\frac{3 R T}{\mathrm{M}_0}} \\
& \therefore \mathrm{V}^2=\frac{3 \mathrm{RT}}{\mathrm{M}_0} \\
& \therefore \frac{\mathrm{V}^2}{\mathrm{~T}}=\frac{3 \mathrm{R}}{\mathrm{M}_0}=\text { constant }
\end{aligned}
$$

The r.m.s. velocity of a molecule is given by
$$
\begin{aligned}
\mathrm{C} &=\sqrt{\frac{3 \mathrm{RT}}{\mathrm{M}}} \\
\therefore \frac{\mathrm{C}_{\mathrm{H}}}{\mathrm{C}_{\mathrm{o}}} &=\sqrt{\frac{\mathrm{T}_{\mathrm{H}}}{\mathrm{T}_{\mathrm{o}}} \cdot \frac{\mathrm{M}_{\mathrm{o}}}{\mathrm{M}_{\mathrm{H}}}} \\
\therefore \mathrm{C}_{\mathrm{H}} &=\mathrm{C}_{\mathrm{o}} \\
\frac{\mathrm{T}_{\mathrm{H}}}{\mathrm{T}_{\mathrm{o}}} \cdot & \frac{\mathrm{M}_{0}}{\mathrm{M}_{\mathrm{H}}}=1, \quad \mathrm{~T}_{\mathrm{H}}=47+273=320 \\
\therefore \mathrm{T}_{\mathrm{H}} &=\frac{\mathrm{M}_{\mathrm{H}}}{\mathrm{M}_{\mathrm{o}}} \cdot \mathrm{T}_{\mathrm{o}}=\frac{2}{32} \cdot 320=20 \mathrm{~K}
\end{aligned}
$$

The average velocity
$$
\begin{aligned}
v_{\mathrm{av}} &=\frac{v_{1}+v_{2}+v_{3} \ldots v_{n}}{N} \\
&=\frac{1+3+5+7}{4}=4 \mathrm{~km} / \mathrm{s}
\end{aligned}
$$
Root mean square velocity
$$
v_{\mathrm{rms}}=\sqrt{\frac{v_{1}^{2}+v_{2}^{2}+v_{3}^{2}+v_{4}^{2}+\ldots+v_{n}^{2}}{N}}
$$
$$
\begin{array}{l}
=\sqrt{\frac{1+(3)^{2}+(5)^{2}+(7)^{2}}{4}} \\
=\sqrt{21}=4.583 \mathrm{~km} / \mathrm{s}
\end{array}
$$
Difference between average velocity and root mean square velocity $=4.583-4$
$$
=0.583 \mathrm{~km} / \mathrm{s}
$$

